<?php

namespace Database\Seeders;

use App\Application\Actions\Contests\ImportContestsFromCsvAction;
use App\Domain\Contests\Models\Contest;
use App\Domain\Runners\Models\Runner;
use App\Domain\Users\Models\User;
use Carbon\CarbonImmutable;
use Illuminate\Database\Seeder;

class DatabaseSeeder extends Seeder
{
    /**
     * Seed the application's database.
     *
     * Model events stay on: the slug of a custom field is generated by an observer.
     */
    public function run(ImportContestsFromCsvAction $importContests): void
    {
        User::factory()->admin()->create([
            'name' => 'Admin',
            'email' => 'admin@example.com',
            'password' => 'password',
        ]);

        $this->call(RunnerPreferenceSeeder::class);

        $importContests->execute(database_path('data/contests.csv'));

        $contest = Contest::query()
            ->where('registrations_open', true)
            ->orderBy('available_places')
            ->firstOrFail();

        Runner::factory(5)
            ->create()
            ->each(function (Runner $runner) use ($contest): void {
                $runner->setCustomFields(['taglia-maglietta' => 'm', 'newsletter' => true]);

                $contest->runners()->attach($runner->id, ['registered_at' => CarbonImmutable::now()]);
            });
    }
}
